using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public static class SeedData
{
    public static async Task InitializeAsync(ApplicationDbContext db)
    {
        if (db.Shipments.Any()) return;

        var now = DateTime.UtcNow;

        db.Shipments.AddRange(
            new Shipment
            {
                TrackingNumber = "TRK-20260001",
                Origin = "New York, NY",
                Destination = "Los Angeles, CA",
                Status = 2, // InTransit
                CreatedAt = now.AddDays(-3),
                EstimatedDelivery = now.AddDays(2),
                RecipientName = "Alice Johnson",
                Description = "Electronics - 2 boxes"
            },
            new Shipment
            {
                TrackingNumber = "TRK-20260002",
                Origin = "Chicago, IL",
                Destination = "Miami, FL",
                Status = 0, // Pending
                CreatedAt = now.AddDays(-1),
                EstimatedDelivery = now.AddDays(5),
                RecipientName = "Bob Smith",
                Description = "Furniture - 1 pallet"
            },
            new Shipment
            {
                TrackingNumber = "TRK-20260003",
                Origin = "Seattle, WA",
                Destination = "Denver, CO",
                Status = 4, // Delivered
                CreatedAt = now.AddDays(-7),
                EstimatedDelivery = now.AddDays(-2),
                ActualDelivery = now.AddDays(-2),
                RecipientName = "Carol Davis",
                Description = "Office supplies - 3 cartons"
            },
            new Shipment
            {
                TrackingNumber = "TRK-20260004",
                Origin = "Houston, TX",
                Destination = "Phoenix, AZ",
                Status = 3, // OutForDelivery
                CreatedAt = now.AddDays(-4),
                EstimatedDelivery = now,
                RecipientName = "David Lee",
                Description = "Auto parts - 1 crate"
            },
            new Shipment
            {
                TrackingNumber = "TRK-20260005",
                Origin = "Boston, MA",
                Destination = "Atlanta, GA",
                Status = 1, // PickedUp
                CreatedAt = now.AddHours(-6),
                EstimatedDelivery = now.AddDays(4),
                RecipientName = "Eva Martinez",
                Description = "Medical equipment - 2 boxes"
            }
        );

        await db.SaveChangesAsync();
    }
}

