// Add additional endpoints required by the Identity /Account Razor components.
app.MapAdditionalIdentityEndpoints();

// Shipment API endpoints
var shipments = app.MapGroup("/api/shipments").RequireAuthorization();

shipments.MapGet("/", async (ShipmentStatus? status, IShipmentService service) =>
    Results.Ok(await service.GetShipmentsAsync(status)));

shipments.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
{
    var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
    return shipment is null ? Results.NotFound() : Results.Ok(shipment);
});

shipments.MapPut("/{id:int}/status", async (int id, StatusUpdateRequest request, IShipmentService service) =>
{
    var shipment = await service.UpdateShipmentStatusAsync(id, request.Status);
    return shipment is null ? Results.NotFound() : Results.Ok(shipment);
}).RequireAuthorization("Dispatcher");

// Authorization policies
builder = null; // Prevent accidental use after build

app.Run();

public record StatusUpdateRequest(ShipmentStatus Status);

