                       @bind="searchInput" @bind:event="oninput"
                       @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="Search" disabled="@isSearching">
                    @if (isSearching)
                    {
                        <span class="spinner-border spinner-border-sm" role="status"></span>
                    }
                    else
                    {
                        <text>Search</text>
                    }
                </button>
            </div>
        </div>
    </div>

    @if (notFound)
    {
        <div class="alert alert-warning">
            No shipment found with tracking number <strong>@lastSearched</strong>. Please check the number and try again.
        </div>
    }
    else if (errorMessage is not null)
    {
        <div class="alert alert-danger">@errorMessage</div>
    }
    else if (shipment is not null)
    {
        <div class="card shadow-sm">
            <div class="card-header d-flex justify-content-between align-items-center">
                <h5 class="mb-0">Shipment @shipment.TrackingNumber</h5>
                <span class="@shipment.StatusBadgeClass fs-6">@shipment.StatusDisplay</span>
            </div>
            <div class="card-body">
                <div class="row">
                    <div class="col-md-6">
                        <dl>
                            <dt>Recipient</dt>
                            <dd>@shipment.RecipientName</dd>

                            <dt>Description</dt>
                            <dd>@shipment.Description</dd>

                            <dt>Origin</dt>
                            <dd>@shipment.Origin</dd>

                            <dt>Destination</dt>
                            <dd>@shipment.Destination</dd>
                        </dl>
                    </div>
                    <div class="col-md-6">
                        <dl>
                            <dt>Shipped On</dt>
                            <dd>@shipment.CreatedAt.ToString("MMMM dd, yyyy")</dd>

                            <dt>Estimated Delivery</dt>
                            <dd>
                                @if (shipment.EstimatedDelivery.HasValue)
                                {
                                    <span class="fw-bold text-primary">
                                        @shipment.EstimatedDelivery.Value.ToString("MMMM dd, yyyy")
                                    </span>
                                }
                                else
                                {
                                    <span class="text-muted">Not available</span>
                                }
                            </dd>

                            @if (shipment.ActualDelivery.HasValue)
                            {
                                <dt>Delivered On</dt>
                                <dd>
                                    <span class="text-success fw-bold">
                                        @shipment.ActualDelivery.Value.ToString("MMMM dd, yyyy 'at' h:mm tt")
                                    </span>
                                </dd>
                            }
                        </dl>
                    </div>
                </div>

                <!-- Progress tracker -->
                <hr />
                <h6>Shipment Progress</h6>
                <div class="d-flex justify-content-between mt-3">
                    @foreach (var step in progressSteps)
                    {
                        var isActive = (int)shipment.Status >= step.order;
                        var isCurrent = (int)shipment.Status == step.order;
                        <div class="text-center flex-fill">
                            <div class="rounded-circle d-inline-flex align-items-center justify-content-center @(isActive ? "bg-primary text-white" : "bg-light text-muted") @(isCurrent ? "border border-3 border-primary" : "")"
                                 style="width: 40px; height: 40px;">
                                @step.icon
                            </div>
                            <div class="small mt-1 @(isActive ? "fw-bold" : "text-muted")">@step.label</div>
                        </div>
                    }
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter]
    public string? TrackingNumber { get; set; }

    private string searchInput = string.Empty;
    private ShipmentDto? shipment;
    private bool isSearching;
    private bool notFound;
    private string? errorMessage;
    private string? lastSearched;

    private readonly (int order, string icon, string label)[] progressSteps =
    [
        (0, "📝", "Pending"),
        (1, "📦", "Picked Up"),
        (2, "🚚", "In Transit"),
        (3, "🏠", "Out for Delivery"),
        (4, "✅", "Delivered")
    ];

    protected override async Task OnInitializedAsync()
    {
        if (!string.IsNullOrWhiteSpace(TrackingNumber))
        {
            searchInput = TrackingNumber;
            await Search();
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await Search();
    }

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(searchInput)) return;

        try
        {
            isSearching = true;
            notFound = false;
            errorMessage = null;
            lastSearched = searchInput.Trim();

            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(lastSearched);
            notFound = shipment is null;
        }
        catch (Exception ex)
        {
            errorMessage = $"Error searching for shipment: {ex.Message}";
            shipment = null;
        }
        finally
        {
            isSearching = false;
        }
    }
}

