@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<div class="container-fluid mt-3">
    <h2>📋 Dispatcher Dashboard</h2>

    <div class="row mb-3">
        <div class="col-md-4">
            <label class="form-label">Filter by Status</label>
            <select class="form-select" @onchange="OnStatusFilterChanged">
                <option value="">All Statuses</option>
                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                {
                    <option value="@((int)status)">@StatusLabel(status)</option>
                }
            </select>
        </div>
        <div class="col-md-4">
            <label class="form-label">Search</label>
            <input type="text" class="form-control" placeholder="Search by tracking #, destination, or recipient"
                   @bind="searchTerm" @bind:event="oninput" />
        </div>
    </div>

    @if (isLoading)
    {
        <div class="d-flex justify-content-center my-5">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else if (errorMessage is not null)
    {
        <div class="alert alert-danger">@errorMessage</div>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-hover align-middle">
                <thead class="table-light">
                    <tr>
                        <th>Tracking #</th>
                        <th>Recipient</th>
                        <th>Origin</th>
                        <th>Destination</th>
                        <th>Status</th>
                        <th>Est. Delivery</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var shipment in FilteredShipments)
                    {
                        <tr>
                            <td><strong>@shipment.TrackingNumber</strong></td>
                            <td>@shipment.RecipientName</td>
                            <td>@shipment.Origin</td>
                            <td>@shipment.Destination</td>
                            <td><span class="@shipment.StatusBadgeClass">@shipment.StatusDisplay</span></td>
                            <td>@shipment.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
                            <td>
                                @if (shipment.Status != ShipmentStatus.Delivered && shipment.Status != ShipmentStatus.Cancelled)
                                {
                                    <div class="dropdown">
                                        <button class="btn btn-sm btn-outline-secondary dropdown-toggle"
                                                type="button" data-bs-toggle="dropdown"
                                                disabled="@(updatingId == shipment.Id)">
                                            @if (updatingId == shipment.Id)
                                            {
                                                <span class="spinner-border spinner-border-sm" role="status"></span>
                                            }
                                            else
                                            {
                                                <text>Update</text>
                                            }
                                        </button>
                                        <ul class="dropdown-menu">
                                            @foreach (var nextStatus in GetNextStatuses(shipment.Status))
                                            {
                                                var s = nextStatus;
                                                <li>
                                                    <button class="dropdown-item" @onclick="() => UpdateStatus(shipment.Id, s)">
                                                        @StatusLabel(s)
                                                    </button>
                                                </li>
                                            }
                                        </ul>
                                    </div>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        @if (!FilteredShipments.Any())
        {
            <div class="text-center text-muted my-4">
                <p>No shipments match your criteria.</p>
            </div>
        }
    }
</div>

@code {
    private List<ShipmentDto> shipments = [];
    private bool isLoading = true;
    private string? errorMessage;
    private ShipmentStatus? statusFilter;
    private string searchTerm = string.Empty;
    private int? updatingId;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        string.IsNullOrWhiteSpace(searchTerm)
            ? shipments
            : shipments.Where(s =>
                s.TrackingNumber.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
                s.Destination.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
                s.RecipientName.Contains(searchTerm, StringComparison.OrdinalIgnoreCase));

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            shipments = await ShipmentService.GetShipmentsAsync(statusFilter);
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load shipments: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task OnStatusFilterChanged(ChangeEventArgs e)
    {
        statusFilter = string.IsNullOrEmpty(e.Value?.ToString())
            ? null
            : (ShipmentStatus)int.Parse(e.Value.ToString()!);
        await LoadShipments();
    }

    private async Task UpdateStatus(int id, ShipmentStatus newStatus)
    {
        try
        {
            updatingId = id;
            var updated = await ShipmentService.UpdateShipmentStatusAsync(id, newStatus);
            if (updated is not null)
            {
                var index = shipments.FindIndex(s => s.Id == id);
                if (index >= 0)
                    shipments[index] = updated;
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to update shipment: {ex.Message}";
        }
        finally
        {
            updatingId = null;
        }
    }

    private static string StatusLabel(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "Pending",
        ShipmentStatus.PickedUp => "Picked Up",
        ShipmentStatus.InTransit => "In Transit",
        ShipmentStatus.OutForDelivery => "Out for Delivery",
        ShipmentStatus.Delivered => "Delivered",
        ShipmentStatus.Cancelled => "Cancelled",
        _ => status.ToString()
    };

    private static ShipmentStatus[] GetNextStatuses(ShipmentStatus current) => current switch
    {
        ShipmentStatus.Pending => [ShipmentStatus.PickedUp, ShipmentStatus.Cancelled],
        ShipmentStatus.PickedUp => [ShipmentStatus.InTransit, ShipmentStatus.Cancelled],
        ShipmentStatus.InTransit => [ShipmentStatus.OutForDelivery, ShipmentStatus.Cancelled],
        ShipmentStatus.OutForDelivery => [ShipmentStatus.Delivered, ShipmentStatus.Cancelled],
        _ => []
    };
}
